import Redis from 'ioredis';
const publisher = new Redis();
const subscriber = new Redis();

async function updateProductAndPropagate(productId, updates) {
  await db.products.update({ where: { id: productId }, data: updates });

  await publisher.publish(
    'cache-invalidation',
    JSON.stringify({ key: `product:${productId}:details` })
  );
}

subscriber.subscribe('cache-invalidation');
subscriber.on('message', (channel, message) => {
  const { key } = JSON.parse(message);
  subscriber.del(key);
});

public async Task<string> GetProductDetailsAsync(int productId, CancellationToken ct)
{
    var db = _redis.GetDatabase();

    var version = await _dbContext.Products
        .Where(p => p.Id == productId)
        .Select(p => p.CacheVersion)
        .SingleAsync(ct);

    var key = $"product:{productId}:v{version}:details";
    var cached = await db.StringGetAsync(key);

    if (cached.HasValue) return cached.ToString();

    var product = await _dbContext.Products.FindAsync([productId], ct);
    var json = JsonSerializer.Serialize(product);
    await db.StringSetAsync(key, json, TimeSpan.FromMinutes(10));

    return json;
}
